import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
    static List<Long> sequenceNumbers = new ArrayList<>();

    public static long calculate(long n, int l) {
        long count = n / sequenceNumbers.get(l);
        n %= sequenceNumbers.get(l);
        if (n == 0) {
            return count * l;
        }
        long val1 = sequenceNumbers.get(l) - n;
        long res1 = calculate(val1, l - 1);
        long res2 = calculate(n, l - 1);
        return count * l + Math.min(l + res1, res2);
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int t = 1;
        for (int i = 0; i < 17; i++) {
            if (i == 0) {
                sequenceNumbers.add(0L);
            } else {
                sequenceNumbers.add(sequenceNumbers.get(i - 1) * 10 + 1);
            }
        }
        while (t-- > 0) {
            long n = scanner.nextLong();
            System.out.println(calculate(n, 16));
        }
        scanner.close();
    }
}
